import type { ReactNode } from "react";

/** A list row that slides sideways to show actions behind it, such as archive or delete. Swiping is a shortcut: the same actions are reachable with a button and the keyboard, so nobody depends on the gesture. Actions can sit on either side, can be turned off per person, and the row stays scrollable up and down. */
export interface SwipeableRowSpecProps {
  /**
   * The row's content. It sits on an opaque surface that covers the actions until it is moved. Put any buttons or links the row needs inside it as usual.
   */
  children: ReactNode;
  /**
   * Actions behind the start of the row, revealed by swiping toward the end: { id, label, icon?, tone?, onAction, permission? }. Keep to one to three. tone is "default", "primary" or "danger". An action may carry a permission ("allow", "disabled", "hidden" or { state, reason }): hidden actions are not drawn; disabled ones stay as focusable, inactive buttons with the reason read out.
   */
  startActions?: import("../swipeable-row/swipeable-row").SwipeAction[];
  /**
   * Actions behind the end of the row, revealed by swiping toward the start. Same shape as startActions. Reading direction is followed, so in a right-to-left page the sides swap with the text.
   */
  endActions?: import("../swipeable-row/swipeable-row").SwipeAction[];
  /**
   * Accessible name of the button that shows the actions without a swipe, and of the group of actions. Name the row in it: "Actions for invoice 1042".
   * @default "Row actions"
   */
  actionsLabel?: string;
  /**
   * Which side is open, to control it. Pass null to keep the row closed. Use with onOpenChange. Leave it out to let the row manage itself.
   */
  open?: "start" | "end" | null;
  /**
   * Which side starts open when you do not control it.
   */
  defaultOpen?: "start" | "end" | null;
  /**
   * Called with the side that is now open, or null when the row closed.
   */
  onOpenChange?: (side: "start" | "end" | null) => void;
  /**
   * A long swipe, past most of the row's width, runs the first action of that side and closes the row. Use it only for actions that are easy to undo: archive, not delete.
   * @default false
   */
  fullSwipe?: boolean;
  /**
   * Close the row after an action runs.
   * @default true
   */
  closeOnAction?: boolean;
  /**
   * Turn swiping off. The actions stay reachable with the button and the keyboard.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Class names for the parts, by slot name, added after the built-in ones. Slots: root, content, actions, action, toggle.
   */
  classNames?: Partial<Record<"root" | "content" | "actions" | "action" | "toggle", string>>;
}

export const swipeableRowDefaults = {
  actionsLabel: "Row actions",
  fullSwipe: false,
  closeOnAction: true,
  isDisabled: false,
} as const;

export const swipeableRowMeta = {
  "name": "SwipeableRow",
  "version": "0.1.0",
  "status": "experimental",
  "role": "group"
} as const;
